<?php
 namespace Pterodactyl\Services\Dezerx\Staff; use Illuminate\Support\Collection; use Pterodactyl\Exceptions\DisplayException; use Pterodactyl\Models\Dezerx\StaffMessage; use Pterodactyl\Models\Dezerx\StaffRequest; use Pterodactyl\Models\User; class StaffChat { public const PAGE = 40; public static function canRead(StaffRequest $request, User $user): bool { if ($user->root_admin === true) { return true; } if ((int) $request->staff_id === $user->id) { return true; } $server = $request->server; return $server !== null && (int) $server->owner_id === $user->id; } public static function canWrite(StaffRequest $request, User $user): bool { if (!$request->isActive()) { return false; } if ($user->root_admin === true) { return true; } if ((int) $request->staff_id === $user->id) { return true; } $server = $request->server; return $server !== null && (int) $server->owner_id === $user->id; } public static function messages(StaffRequest $request, int $after = 0, int $before = 0): Collection { $query = StaffMessage::query() ->with('author:id,username,email,dezerx_preferences') ->where('request_id', $request->id); if ($after > 0) { return $query->where('id', '>', $after)->orderBy('id')->limit(self::PAGE)->get(); } return $query ->when($before > 0, fn ($inner) => $inner->where('id', '<', $before)) ->orderByDesc('id') ->limit(self::PAGE) ->get() ->reverse() ->values(); } public static function hasOlder(StaffRequest $request, int $before): bool { return $before > 0 && StaffMessage::query() ->where('request_id', $request->id) ->where('id', '<', $before) ->exists(); } public static function post(StaffRequest $request, User $user, string $body): StaffMessage { if (!Staff::enabled()) { throw new DisplayException('The support staff system is switched off on this panel.'); } if (!self::canWrite($request, $user)) { throw new DisplayException('That session is not open for messages.'); } $text = self::clean($body); if ($text === '') { throw new DisplayException('Write something first.'); } $count = StaffMessage::query()->where('request_id', $request->id)->count(); if ($count >= StaffMessage::MAX_PER_REQUEST) { throw new DisplayException('This conversation has reached its message limit.'); } $message = StaffMessage::query()->create([ 'request_id' => $request->id, 'user_id' => $user->id, 'body' => $text, 'created_at' => now(), ]); self::markRead($request, $user); StaffNotify::message($request, $user, $text); return $message; } public static function markRead(StaffRequest $request, User $user): void { $server = $request->server; $field = null; if ((int) $request->staff_id === $user->id) { $field = 'staff_read_at'; } elseif ($server !== null && (int) $server->owner_id === $user->id) { $field = 'owner_read_at'; } if ($field === null) { return; } $request->forceFill([$field => now()])->saveOrFail(); } public static function unreadFor(StaffRequest $request, User $user): int { $server = $request->server; if ((int) $request->staff_id === $user->id) { $since = $request->staff_read_at; } elseif ($server !== null && (int) $server->owner_id === $user->id) { $since = $request->owner_read_at; } else { return 0; } return StaffMessage::query() ->where('request_id', $request->id) ->where('user_id', '!=', $user->id) ->when($since !== null, fn ($query) => $query->where('created_at', '>', $since)) ->count(); } public static function clean(string $body): string { $text = str_replace(["\r\n", "\r"], "\n", trim($body)); $text = preg_replace('/\n{3,}/', "\n\n", $text) ?? ''; $text = preg_replace('/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/u', '', $text) ?? ''; return mb_substr(trim($text), 0, StaffMessage::MAX_LENGTH); } } 